import type { InjectionKey } from "vue";
import { inject } from "vue";
import { isInIframeRealm, isInWujie } from "./sandbox";

/**
 * TuDesignProvider 应用级显式配置层（plan: tu-design-provider-mode）。
 *
 * 动机：自动探测（marker / realm / 结构信号）存在固有边界——marker 随 wujie 版本漂移、
 * degrade 模式无法区分、故障静默。本模块新增手动声明层，解析优先级：
 *   组件显式 prop（to / positioning.strategy 等，已有） > Provider mode（本模块） > 自动探测（auto 缺省）。
 *
 * mode 语义 = 「隔离构成」行为组，判据是拓扑而非框架品牌（机制详注见 sandbox.ts 头注）：
 * - none          = { }                                // 独立运行 / qiankun / micro-app lightDOM / 纯 iframe 嵌入 / wujie degrade
 * - shadow        = { teleport降级 }                   // micro-app strictStyleIsolation / web component
 * - shadow-iframe = { teleport降级, fixed策略, 锁禁用 } // wujie 默认模式（iframe realm + shadow graft 双重隔离）
 * - auto（缺省）  = 现行探测链，行为与历史版本逐字节一致
 *
 * 纪律：
 * - 显式 mode 一律短路，不进入任何探测代码（marker 漂移免疫的可证性质）；
 * - mode 只表达渲染环境单维度；新的根部能力走 Provider 命名空间对象 prop（present = enabled），
 *   且每个 prop 必须注明 mount-time / reactive（缺省 mount-time）；
 * - `none` 是「显式关全部适配」，不保证与 auto 逐位等值（如纯 iframe 下 auto 会注入无害 fixed）。
 */

/** 渲染环境声明（行为组名，非框架名） */
export type TuProviderMode = "auto" | "none" | "shadow" | "shadow-iframe";

/** Provider 注入的配置快照（mount-time 消费；动态变更用 :key 重挂载） */
export interface TuProviderConfig {
  mode: TuProviderMode;
  /**
   * overlay 命名空间 prop（present = enabled，mount-time；issue #5）。
   * 可选键：既有 provide({ mode }) 字面量与 DEFAULT_CONFIG 不受影响。
   */
  overlay?: TuOverlayContract;
}

/** provide/inject 契约键（沿逻辑树传递，Teleport 子树同样命中） */
export const TU_PROVIDER_KEY: InjectionKey<TuProviderConfig> = Symbol("tu-provider");

const DEFAULT_CONFIG: TuProviderConfig = { mode: "auto" };

/**
 * 读取应用级配置；无 Provider 时缺省 auto（= 未引入本特性前的行为，向后兼容兜底）。
 * 须在 setup 顶层调用（inject 约束）。
 * @returns 最近 Provider 的配置快照，或 { mode: "auto" }
 */
export function useTuProvider(): TuProviderConfig {
  return inject(TU_PROVIDER_KEY, DEFAULT_CONFIG);
}

/**
 * Teleport 目标降级判定：shadow / shadow-iframe → 降级到应用挂载容器；
 * none → 恒 body；auto → 现行 isInWujie 探测（结构 shadowRoot 信号在
 * useSandboxTeleportTarget 内与本结果 OR，仅 auto 分支参与）。
 * @param mode 环境声明
 * @returns 是否强制降级（显式 mode 下不执行任何探测）
 */
export function teleportDegrade(mode: TuProviderMode): boolean {
  switch (mode) {
    case "none":
      return false;
    case "shadow":
    case "shadow-iframe":
      return true;
    case "auto":
      return isInWujie();
  }
}

/**
 * positioning.strategy 缺省 fixed 判定：仅 shadow-iframe（iframe realm + graft 坐标错位）
 * 与 auto 的 isInIframeRealm 探测注入；用户显式 strategy 的优先级在调用方
 * （withSandboxStrategy）先行短路。
 * @param mode 环境声明
 * @returns 用户未指定 strategy 时是否注入 fixed
 */
export function strategyFixed(mode: TuProviderMode): boolean {
  switch (mode) {
    case "none":
    case "shadow":
      return false;
    case "shadow-iframe":
      return true;
    case "auto":
      return isInIframeRealm();
  }
}

/**
 * 模态滚动锁策略：shadow-iframe → false（禁用，issue #4 的 graft 坐标系误补偿）；
 * none / shadow → undefined（交还 Ark preventScroll=modal 派生默认）；
 * auto → 现行 isInWujie ? false : undefined。
 * 传硬编码 true 永远禁止——attrs 透传 :modal=false 的既有用法会被强加滚动锁（行为回归）。
 * @param mode 环境声明
 * @returns false=显式禁用；undefined=不覆盖 Ark 缺省
 */
export function preventScrollOverride(mode: TuProviderMode): boolean | undefined {
  switch (mode) {
    case "none":
    case "shadow":
      return undefined;
    case "shadow-iframe":
      return false;
    case "auto":
      return isInWujie() ? false : undefined;
  }
}

/**
 * overlay 滚动锁契约（issue #5）：消费方提供 lock() → 解锁函数，
 * 契约层只负责「是否消费」的拓扑判定，不包装、不持有状态。
 */
export interface TuOverlayContract {
  lock(): VoidFunction;
}

/**
 * overlay 契约消费判定（语义 B：仅锁禁用拓扑消费，issue #5）。
 * overlay 命名空间 prop present = enabled，mount-time 消费；
 * 仅当 preventScrollOverride(mode) === false（shadow-iframe 显式 / auto 探测命中 wujie）
 * 时透传契约引用，其余拓扑（none / shadow / auto 非 wujie / 未提供 overlay）一律 null。
 * 显式 mode 短路探测的性质由 preventScrollOverride 继承（marker 漂移免疫）。
 * @param config Provider 配置快照
 * @returns 锁禁用拓扑下为 config.overlay 同引用，否则 null
 */
export function overlayContract(config: TuProviderConfig): TuOverlayContract | null {
  return config.overlay && preventScrollOverride(config.mode) === false ? config.overlay : null;
}

import { ref, type ComponentInternalInstance } from "vue";

export interface ConfirmPendingOptions {
  /** 当前组件实例：从 vnode 上取原始 onConfirm 监听器（emit 不回传返回值） */
  instance: ComponentInternalInstance | null;
  /** 无监听器时补发 confirm 事件 */
  emitConfirm: () => void;
  emitCancel: () => void;
  /** 关闭弹层（走受控桥） */
  close: () => void;
}

/**
 * 确认弹层公共 pending 语义：@confirm 处理器返回 Promise 时锁定关闭通道，
 * resolve 后自动关闭，reject 保持打开并退出 loading；同步处理器直接关闭。
 * @param options - pending 配置：组件实例、confirm/cancel 补发与弹层关闭回调
 * @returns loading（确认进行中标记）、handleConfirm（异步确认处理）与 handleCancel（取消处理）
 */
export function useConfirmPending(options: ConfirmPendingOptions) {
  const loading = ref(false);

  function handleConfirm() {
    if (loading.value) return;
    const handler = options.instance?.vnode.props?.onConfirm as
      | ((...args: unknown[]) => unknown)
      | undefined;
    const result = handler?.();
    if (!handler) options.emitConfirm();
    if (result instanceof Promise) {
      loading.value = true;
      result
        .then(() => {
          loading.value = false;
          options.close();
        })
        .catch(() => {
          loading.value = false;
        });
    } else {
      options.close();
    }
  }

  function handleCancel() {
    if (loading.value) return;
    options.emitCancel();
    options.close();
  }

  return { loading, handleConfirm, handleCancel };
}

import { computed, ref, type ComputedRef } from "vue";

export interface ControlledBooleanOptions {
  /** 受控值；返回 undefined 表示非受控（内部状态接管） */
  controlled: () => boolean | undefined;
  /** 非受控初始值 */
  defaultValue?: () => boolean;
  /** 状态变更对外同步（一般 emit("update:open", next)） */
  onChange?: (next: boolean) => void;
}

export interface ControlledBoolean {
  isOpen: ComputedRef<boolean>;
  setOpen: (next: boolean) => void;
}

/**
 * 业务组件惯例：Ark Root 恒走受控，非受控语义由内部 ref 实现。
 * `controlled()` 返回 undefined 时用内部值，否则永远跟随外部 prop。
 * @param options - 受控/非受控配置：受控值读取器、非受控初值与变更回调
 * @returns isOpen（当前开合状态）与 setOpen（写入状态并同步 onChange）
 */
export function useControlledBoolean(options: ControlledBooleanOptions): ControlledBoolean {
  const internal = ref(options.defaultValue?.() ?? false);
  const isOpen = computed(() => options.controlled() ?? internal.value);

  function setOpen(next: boolean) {
    internal.value = next;
    options.onChange?.(next);
  }

  return { isOpen, setOpen };
}

import { computed, useId } from "vue";

/** 与 zag ids 兼容的宽类型：string 或函数型（如 select 的 item(value) => string） */
export type OverlayIds = Record<string, string | ((value: string) => string)>;

/**
 * 浮层组件 ids 全量覆盖（无冒号化）。
 *
 * 背景：zag 缺省 id 惯例形如 `popover:{scope.id}:title`（各包 *.dom.js get*Id
 * 兜底分支），而部分 part 元素并不总是渲染（title/description/anchor/clearTrigger/
 * arrow 等），machine 仍会按状态变更反复 getById 查询。wujie 沙箱把
 * document.getElementById patch 成 `querySelector('[id="…"]')` miss 后兜底
 * `querySelector('#'+id)`（wujie proxy.js），冒号未转义 → SyntaxError → catch 打出
 * "[wujie warn] 不支持document.getElementById()传入特殊字符…" 且打开期间反复刷屏。
 * ids 派生自 Vue useId()（v-0 格式，无冒号）后，未命中也是合法选择器，静默返回
 * null，告警消除；原生环境 getElementById 不解析选择器，行为零变化。
 *
 * 用法（组件 setup 内，inheritAttrs: false 透传模式下同样适用）：
 *   const { ids, resolveId } = useOverlayIds(attrs, {
 *     primary: "content",
 *     parts: ["title", "description", "anchor", "trigger", "closeTrigger", "positioner", "arrow"],
 *   });
 *   // 模板：<ArkXxx.Root v-bind="attrs" :ids="ids">（:ids 须位于 v-bind="attrs" 之后）
 *   // aria 手动接线取元素 id 时用 resolveId(part)（user 覆盖优先，与实际 DOM 一致）
 *
 * 边界：parts 只声明「字符串型覆盖口」的 part；函数型 part（如 select 的
 * item/itemGroup/itemGroupLabel——元素必渲染，[id="…"] 首查即命中，无炸点）不进
 * parts，由 user 经 attrs.ids 直传原样保留。user 永远最后展开：显式传入以其为准。
 * @param attrs - 组件透传 attrs（其中的 ids 为用户覆盖项，可为 undefined）
 * @param options - 生成配置：primary 为主 part（stemId 不加后缀），parts 为声明覆盖口的 part 列表
 * @returns ids（合并用户覆盖后的完整 id 映射，供 :ids 受控绑定）与 resolveId（取实际生效的字符串 id，供 aria 手动接线）
 */
export function useOverlayIds(
  attrs: Record<string, unknown>,
  options: { primary: string; parts: readonly string[] },
) {
  const stemId = useId();
  const userIds = computed(() => (attrs.ids ?? {}) as OverlayIds);
  /**
   * 默认派生值（不含 user 覆盖），独立于 ids 供 resolveId 回退；构造恒为字符串。
   * @returns 以 part 为键的默认 id 映射
   */
  const buildBase = (): Record<string, string> => {
    const base: Record<string, string> = {};
    for (const part of options.parts) {
      base[part] = part === options.primary ? stemId : `${stemId}-${part}`;
    }
    return base;
  };
  const ids = computed<OverlayIds>(() => ({ ...buildBase(), ...userIds.value })); // user 永远收尾
  /**
   * aria 接线用：user 字符串覆盖优先，函数型 user 回退默认值。
   * @param part - 目标 part 名（如 "title"、"trigger"）
   * @returns 该 part 实际生效的字符串 id；part 未声明覆盖口时返回 undefined
   */
  const resolveId = (part: string) => {
    const v = userIds.value[part];
    return typeof v === "string" ? v : buildBase()[part];
  };
  return { ids, resolveId };
}

import type { Ref } from "vue";
import { onBeforeUnmount, watch } from "vue";
import { overlayContract, useTuProvider } from "./config";

/**
 * overlay 滚动锁契约消费（issue #5）：wujie graft 下 Ark 原生滚动锁被禁用（issue #4），
 * 「锁背景」改由宿主经 Provider overlay 命名空间 prop 提供 lock() → 解锁函数契约。
 *
 * 设计依据（冻结语义）：
 * - 语义 B 拓扑闸：仅锁禁用拓扑消费契约（overlayContract 内判定，shadow-iframe 显式 /
 *   auto 探测命中 wujie），其余拓扑 setup 顶层直接 return，零 watch 零副作用。
 * - RAII 配对：lock() 返回的 release 与开合状态一一对应——open 且模态时持锁，
 *   关闭/非模态时释放，onBeforeUnmount 补调防泄漏（打开态直接卸载不丢 release）。
 * - sync + immediate：flush:"sync" 使 lock/release 在 isOpen 转换内同步完成，
 *   无 nextTick 窗口、同 tick 快速翻转不合并（true-false-true → lock 2 次 release 1 次）；
 *   immediate 覆盖初始 open=true 的挂载即锁场景。
 * - isModal 仅在 isOpen 转换回调内求值，不 watch attrs：打开期间 modal 变化不触发
 *   锁状态变更（三组件接线 () => attrs.modal !== false && attrs.modal !== "false"）。
 *
 * @param isOpen - 开合状态（受控桥 ComputedRef 或内部 ref 均可）
 * @param isModal - 模态判定读取器（仅转换回调内求值）
 */
export function useOverlayScrollLock(isOpen: Ref<boolean>, isModal: () => boolean): void {
  const contract = overlayContract(useTuProvider());
  if (!contract) return;

  let release: VoidFunction | null = null;

  watch(
    isOpen,
    (open) => {
      if (open && isModal() && !release) {
        release = contract.lock();
      } else if ((!open || !isModal()) && release) {
        release();
        release = null;
      }
    },
    { immediate: true, flush: "sync" },
  );

  onBeforeUnmount(() => {
    if (release) {
      release();
      release = null;
    }
  });
}

import type { ComputedRef } from "vue";
import { computed, getCurrentInstance, onMounted, ref } from "vue";
import {
  type TuProviderConfig,
  preventScrollOverride,
  strategyFixed,
  teleportDegrade,
  useTuProvider,
} from "./config";

/**
 * 浮层沙箱适配公共层（Popover 0.5.3 修复的推广形态，机制与实测依据见 sandbox.ts 头注）：
 * - useSandboxTeleportTarget：Teleport 目标降级（真 shadow DOM / wujie graft → 应用挂载容器）
 * - withSandboxStrategy：iframe realm 下 positioning.strategy 默认 fixed（absolute 包含块错位修正）
 * - overlayPreventScroll：模态浮层滚动锁按沙箱拓扑降级（wujie graft 下禁用，issue #4）
 *
 * 三项均「Provider mode 显式声明优先、缺省 auto 走探测」，解析语义见 config.ts。
 */

/**
 * 浮层 Teleport 目标解析：显式 to > Provider mode / 探测降级 > body。
 *
 * app._container 在 mount 的 render 完成后才赋值（runtime-core 3.5.43：render L4337
 * → 赋值 L4340），而子组件 onMounted 在 render 内同步执行、届时仍为 undefined，
 * 故检测再延后一个微任务（mount 调用栈结束后 _container 必已赋值），结果存 ref
 * 驱动 computed 重算；getCurrentInstance 仅 setup 同步上下文可用，本函数须在
 * setup 顶层调用。共享 Vue（__MICRO_SHARED__）下各子应用 app._container 相互
 * 独立，检测按实例隔离。
 * 降级判定：显式 mode（shadow / shadow-iframe）短路降级、none 恒不降；auto 走现行
 * 双信号——真 shadow DOM 由 getRootNode() 命中，wujie graft 下 getRootNode/父链被
 * patch 伪装（实测）故叠加 marker。结构 shadowRoot 信号仅 auto 分支参与（显式声明
 * 时不再猜测）。其余微前端（qiankun / micro-app light DOM）body 即主文档 body，兜底正确。
 *
 * @param explicitTo 组件显式 to 的取值函数（响应式安全：computed 内重读）
 * @returns Teleport 目标（显式 to 优先，其次降级容器，兜底 body）
 */
export function useSandboxTeleportTarget(
  explicitTo: () => string | HTMLElement | undefined,
): ComputedRef<string | HTMLElement> {
  const instance = getCurrentInstance();
  const { mode } = useTuProvider();
  const degrade = teleportDegrade(mode);
  const detectedTarget = ref<string | HTMLElement>("body");
  onMounted(() => {
    queueMicrotask(() => {
      if (explicitTo()) return;
      const container = (instance?.appContext.app as { _container?: HTMLElement } | undefined)
        ?._container;
      if (
        container &&
        (degrade || (mode === "auto" && container.getRootNode() instanceof ShadowRoot))
      ) {
        detectedTarget.value = container;
      }
    });
  });
  return computed(() => explicitTo() ?? detectedTarget.value);
}

/**
 * 用户未显式指定 strategy 时按环境注入缺省 fixed：shadow-iframe 显式注入、
 * none / shadow 恒不注入、auto 走 isInIframeRealm 探测（非 graft 拓扑下 fixed 与
 * absolute 坐标等价，零副作用；graft 下 absolute 包含块错位，fixed 是唯一正确解）。
 * 优先级：user.strategy > Provider mode/探测 > 不注入。
 * 纯函数、原地写入 merged（调用方传入自己的合成对象，无共享引用风险）；
 * user.strategy 显式给出（含 null 意义上的「未传」判定用 == null）时以其为准。
 * config 须在组件 setup 顶层经 useTuProvider() 捕获后传入（computed 内 inject 不可用）。
 *
 * @param user 用户原始 positioning（undefined 或经 attrs 透传的合成对象）
 * @param merged 组件已合成 placement/sameWidth 等的基础 positioning（将被写入）
 * @param config 应用级沙箱配置快照（setup 顶层 useTuProvider() 结果）
 * @returns 写入 strategy 后的 merged（同引用，便于 computed 直接 return）
 */
export function withSandboxStrategy<T extends object>(
  user: T | undefined,
  merged: T,
  config: TuProviderConfig,
): T {
  if ((user as { strategy?: string } | undefined)?.strategy == null && strategyFixed(config.mode)) {
    (merged as { strategy?: string }).strategy = "fixed";
  }
  return merged;
}

/**
 * 模态浮层滚动锁策略（dialog / alert-dialog / drawer 共用，issue #4）：
 * 按 useTuProvider().mode 解析（shadow-iframe 禁用 / none、shadow 交还缺省 /
 * auto 走 isInWujie 探测）。禁用依据：@zag-js/remove-scroll 的补偿公式
 * `scrollbarWidth = win.innerWidth − documentElement.clientWidth` 在 graft 下跨坐标系
 * （iframe 报宿主视口宽，documentElement 是 graft 进 shadowRoot 的子应用容器），
 * 宿主 chrome 宽被误当滚动条写入渲染 body（padding-right）→ 弹窗开合整页重排抖动；
 * 且主流 wujie 拓扑下子应用 body 本就不滚（滚动在宿主容器），锁无收益只有副作用。
 * 拓扑边界：若子应用 body 自身可滚，禁用后背景随弹窗可滚——带误补偿的锁不如不要，
 * wujie 下真正的「锁背景」需宿主参与（见 plan §6 follow-up）。
 * 传硬编码 true 永远禁止——本库组件单根、attrs 透传，消费方 :modal="false" 的
 * 既有用法会被强加滚动锁（行为回归），undefined 经适配层 cleanProps 过滤后
 * 保留 zag 缺省 preventScroll = modal。
 * 须在 setup 顶层调用（inject 约束）。
 *
 * @returns false=禁用滚动锁；undefined=不覆盖 Ark 缺省
 */
export function overlayPreventScroll(): boolean | undefined {
  return preventScrollOverride(useTuProvider().mode);
}
